WITH flagged AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) + INTERVAL 14 DAYS THEN 1 ELSE 0 END AS is_new_session FROM transactions), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged) SELECT CASE WHEN amount >= 4500 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, APPROX_PERCENTILE(session_id, 0.9) AS session_id_p90, COUNT(*) AS row_count, COUNT(*) FILTER (WHERE txn_type = 'DEBIT') AS debit_rows, ROUND(AVG(session_id), 2) AS avg_session_id, SIZE(COLLECT_SET(txn_type)) AS num_txn_types, SORT_ARRAY(COLLECT_SET(merchant)) AS merchant_list FROM sessionized GROUP BY CASE WHEN amount >= 4500 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING row_count > 1 ORDER BY session_id_p90 NULLS LAST;
